CREATE OR REPLACE FUNCTION public.ppm_snapshot() RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
#variable_conflict use_column
DECLARE result jsonb; u jsonb; roles text[]; BEGIN IF NOT public.ppm_ativo() THEN RAISE EXCEPTION 'Acesso não autorizado' USING ERRCODE='42501'; END IF; SELECT array_agg(papel) INTO roles FROM public.ppm_papeis WHERE user_id=auth.uid(); SELECT jsonb_build_object('id',p.id,'nome',p.display_name,'email',p.email,'cargo',p.job_title,'iniciais',upper(left(p.display_name,2)),'perfil',CASE WHEN 'administrador_pmo'=ANY(roles) THEN 'Administrador/PMO' WHEN 'auditor'=ANY(roles) THEN 'Auditor' WHEN 'alta_administracao'=ANY(roles) THEN 'Alta Administração' WHEN 'gestor'=ANY(roles) THEN 'Gestor' ELSE 'Técnico' END) INTO u FROM public.profiles p WHERE id=auth.uid();
SELECT jsonb_build_object('usuario',u,'capacidades',coalesce(to_jsonb(roles),'[]'),'usuarios',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',display_name,'email',email,'cargo',job_title,'iniciais',upper(left(display_name,2)),'perfil',CASE WHEN id=auth.uid() THEN u->>'perfil' ELSE 'Técnico' END)) FROM public.profiles),'[]'),'areas',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'nome',a.nome,'sigla',a.sigla,'responsavel',a.responsavel,'visibilidade',a.visibilidade,'membros',coalesce((SELECT jsonb_agg(jsonb_build_object('usuarioId',usuario_id,'papel',papel)) FROM public.area_membros WHERE area_id=a.id),'[]'))) FROM public.areas a),'[]'),'objetos',coalesce((SELECT jsonb_object_agg(id,jsonb_build_object('areaId',area_id,'visibilidade',visibilidade,'convidados',convidados,'compartilhadoCom',compartilhado_com)) FROM public.objetos_acesso),'{}'),'permissoes',coalesce((SELECT jsonb_object_agg(id,public.ppm_pode_editar(id)) FROM public.objetos_acesso),'{}'),'portfolios',coalesce((SELECT jsonb_agg(jsonb_build_object('id',f.id,'areaId',f.area_id,'responsavelId',f.responsavel_id,'nome',f.nome,'tipo',f.tipo,'responsavel',f.responsavel,'orcamento',t.orcamento_projetos,'executado',t.executado,'progresso',t.progresso,'saude',f.saude,'prioridade',f.prioridade,'score',f.score,'programas',t.programas,'projetos',t.projetos,'riscosCriticos',t.riscos_criticos)) FROM public.portfolios f JOIN public.totais_portfolio t ON t.id=f.id),'[]'),'programas',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'nome',g.nome,'portfolioId',g.portfolio_id,'gerente',g.gerente,'objetivo',g.objetivo,'saude',g.saude,'progresso',t.progresso,'metas',coalesce((SELECT jsonb_agg(jsonb_build_object('nome',nome,'alvo',alvo,'atual',atual,'unidade',unidade)) FROM public.programa_metas WHERE programa_id=g.id),'[]'))) FROM public.programas g JOIN public.totais_programa t ON t.id=g.id),'[]'),'projetos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'nome',p.nome,'programaId',p.programa_id,'gerente',p.gerente,'metodologia',p.metodologia,'status',p.status,'inicio',p.inicio,'fim',p.fim,'orcamento',p.orcamento,'executado',p.executado,'progresso',p.progresso,'saude',p.saude,'escopo',p.escopo,'objetivoId',coalesce((SELECT objetivo_id::text FROM public.alinhamento_estrategico WHERE objeto_id=p.id LIMIT 1),''))) FROM public.projetos p),'[]'),'objetivos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'codigo',o.codigo,'nome',o.nome,'perspectiva',o.perspectiva,'meta',o.meta,'responsavel',o.responsavel,'aderencia',coalesce((SELECT round(avg(p.progresso),2) FROM public.projetos p JOIN public.alinhamento_estrategico a ON a.objeto_id=p.id WHERE a.objetivo_id=o.id),0))) FROM public.objetivos_estrategicos o),'[]'),'riscos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'nome',r.nome,'categoria',r.categoria,'origem',r.origem,'probabilidade',r.probabilidade,'impacto',r.impacto,'resposta',r.resposta,'plano',coalesce((SELECT string_agg(acao,'; ') FROM public.risco_planos WHERE risco_id=r.id),''),'responsavel',r.responsavel,'prazo',r.prazo,'tendencia',r.tendencia)) FROM public.riscos r),'[]'),'indicadores',coalesce((SELECT jsonb_agg(jsonb_build_object('id',i.id,'nome',i.nome,'formula',i.formula,'unidade',i.unidade,'meta',i.meta,'polaridade',i.polaridade,'periodicidade',i.periodicidade,'responsavel',i.responsavel,'atual',CASE WHEN i.calculo='execucao' THEN (SELECT coalesce(round(100*sum(executado)/nullif(sum(orcamento),0),2),0) FROM public.projetos) WHEN i.calculo='prazo' THEN (SELECT coalesce(round(100.0*count(*) FILTER(WHERE status='Concluído' OR fim>=current_date)/nullif(count(*),0),2),0) FROM public.projetos) ELSE coalesce((SELECT valor FROM public.indicador_valores WHERE indicador_id=i.id ORDER BY periodo DESC LIMIT 1),0) END,'historico',coalesce((SELECT jsonb_agg(jsonb_build_object('periodo',to_char(periodo,'YYYY-MM'),'valor',valor) ORDER BY periodo) FROM public.indicador_valores WHERE indicador_id=i.id),'[]'))) FROM public.indicadores i),'[]'),'elementos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'projetoId',e.projeto_id,'nome',e.nome,'responsavel',e.responsavel,'status',e.status,'prazo',e.prazo,'progresso',e.progresso,'subelementos',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'elementoId',s.elemento_id,'nome',s.nome,'responsavel',s.responsavel,'status',s.status,'prazo',s.prazo,'progresso',s.progresso)) FROM public.projeto_subelementos s WHERE s.elemento_id=e.id),'[]'))) FROM public.projeto_elementos e),'[]'),'atualizacoes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'projetoId',a.projeto_id,'alvoTipo',a.alvo_tipo,'alvoId',a.alvo_id,'autor',a.autor,'criadaEm',a.created_at,'texto',a.texto) ORDER BY a.created_at DESC) FROM public.projeto_atualizacoes a),'[]'),'statusReports',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'projetoId',s.projeto_id,'periodo',s.periodo,'autor',s.autor,'saude',s.saude,'resumo',s.resumo)) FROM public.status_reports s),'[]'),'tarefas',coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'projetoId',t.projeto_id,'titulo',t.titulo,'responsavel',t.responsavel,'status',t.status,'pontos',t.pontos)) FROM public.projeto_tarefas t),'[]'),'cronograma',coalesce((SELECT jsonb_agg(jsonb_build_object('projetoId',t.projeto_id,'fase',t.titulo,'inicio',(t.inicio-p.inicio)/7.0,'duracao',(t.fim-t.inicio)/7.0,'progresso',t.progresso)) FROM public.projeto_tarefas t JOIN public.projetos p ON p.id=t.projeto_id WHERE t.inicio IS NOT NULL AND t.fim IS NOT NULL),'[]'),'views',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'escopo',escopo,'blocos',blocos,'perfis',perfis,'areas',areas)) FROM public.views_usuario),'[]'),'etiquetas',jsonb_build_object('tipo',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'tom',tom)) FROM public.etiquetas_carteira WHERE coluna='tipo'),'[]'),'status',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'tom',tom)) FROM public.etiquetas_carteira WHERE coluna='status'),'[]'),'metodologia',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome,'tom',tom)) FROM public.etiquetas_carteira WHERE coluna='metodologia'),'[]')),'log',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'quando',to_char(created_at AT TIME ZONE 'America/Sao_Paulo','DD/MM/YYYY HH24:MI'),'usuario',coalesce((SELECT display_name FROM public.profiles WHERE id=a.user_id),'Usuário autorizado'),'perfil','','acao',event_type,'entidade',entity_type,'detalhe',a.result)) FROM (SELECT * FROM public.security_audit_log ORDER BY created_at DESC LIMIT 100)a),'[]'),'totais',(SELECT to_jsonb(t) FROM public.totais_institucionais t)) INTO result; RETURN result; END $$;